#include "geometry_buffer_adapter.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <stdexcept>
#include <string>
#include <vector>
namespace garment::geometry_buffer_adapter {
static constexpr double PI=3.14159265358979323846;
static double num(const Json& j,double fallback=0){if(j.is_number())return j.get<double>();if(j.is_boolean())return j.get<bool>()?1:0;if(j.is_string()){try{return std::stod(j.get<std::string>());}catch(...){}}return fallback;}
static double get(const Json& j,const char* k,double fallback=0){return j.is_object()&&j.contains(k)?num(j[k],fallback):fallback;}
static Json obj(const Json& j,const char* k){return j.is_object()&&j.contains(k)?j[k]:Json::object();}
static std::array<double,3> vec(const Json& j){return {get(j,"x"),get(j,"y"),get(j,"z")};}
static float f32(double v){return static_cast<float>(v);}
static Json attr(const std::vector<float>& a,int size,bool dirty=false){return {{"array",a},{"itemSize",size},{"count",a.size()/size},{"needsUpdate",dirty}};}
static std::vector<float> values(const Json& g,const char* key){return g.at("attributes").at(key).at("array").get<std::vector<float>>();}
static void normals(Json& g){auto p=values(g,"position");std::vector<float> n(p.size(),0);const auto& indices=g.at("index");for(size_t k=0;k+2<indices.size();k+=3){int a=indices[k],b=indices[k+1],c=indices[k+2];if(a<0||b<0||c<0||size_t(3*std::max({a,b,c})+2)>=p.size())throw std::runtime_error("face index out of range");double ax=p[3*a]-p[3*b],ay=p[3*a+1]-p[3*b+1],az=p[3*a+2]-p[3*b+2];double cx=p[3*c]-p[3*b],cy=p[3*c+1]-p[3*b+1],cz=p[3*c+2]-p[3*b+2];float x=f32(cy*az-cz*ay),y=f32(cz*ax-cx*az),z=f32(cx*ay-cy*ax);for(int i:{a,b,c}){n[3*i]=f32(n[3*i]+x);n[3*i+1]=f32(n[3*i+1]+y);n[3*i+2]=f32(n[3*i+2]+z);}}
for(size_t i=0;i<n.size();i+=3){double d=std::hypot(double(n[i]),double(n[i+1]),double(n[i+2]));if(d){n[i]=f32(n[i]/d);n[i+1]=f32(n[i+1]/d);n[i+2]=f32(n[i+2]/d);}}g["attributes"]["normal"]=attr(n,3);}
static void sphere(Json& g){auto p=values(g,"position");if(p.empty()){g["boundingSphere"]={{"center",{0,0,0}},{"radius",0}};return;}std::array<double,3> lo={p[0],p[1],p[2]},hi=lo;for(size_t i=0;i<p.size();i+=3)for(int d=0;d<3;d++){lo[d]=std::min(lo[d],double(p[i+d]));hi[d]=std::max(hi[d],double(p[i+d]));}std::array<double,3> center={(lo[0]+hi[0])/2,(lo[1]+hi[1])/2,(lo[2]+hi[2])/2};double rad=0;for(size_t i=0;i<p.size();i+=3){double d=0;for(int k=0;k<3;k++)d+=std::pow(p[i+k]-center[k],2);rad=std::max(rad,d);}g["boundingSphere"]={{"center",center},{"radius",std::sqrt(rad)}};}
Json updateGeometryFabricUV(const Json& piece,const Json& geometry,const Json& fabric){Json g=geometry;auto flat=piece.at("flatVertices");if(!g.contains("attributes")||!g["attributes"].contains("uv")||size_t(g["attributes"]["uv"].value("count",0))!=flat.size())return {{"updated",false},{"geometry",g}};Json texture=obj(fabric,"texture");double width=get(texture,"repeatWidthCm",20),height=get(texture,"repeatHeightCm",20);width=std::max(.5,width==0?20:width);height=std::max(.5,height==0?20:height);double rad=get(obj(piece,"piece"),"grainAngleDeg")*PI/180,c=std::cos(-rad),s=std::sin(-rad);std::vector<float> uv;uv.reserve(flat.size()*2);for(const auto& v:flat){double x=get(v,"x"),y=get(v,"y");uv.push_back(f32((x*c-y*s)/width));uv.push_back(f32((x*s+y*c)/height));}g["attributes"]["uv"]=attr(uv,2,true);return {{"updated",true},{"geometry",g}};}
Json createGeometry(const Json& piece){std::vector<float> pos,col,uv;const auto& particles=piece.at("particles");for(const auto& p:particles){auto v=vec(p.at("position"));for(double a:v)pos.push_back(f32(a));for(int i=0;i<3;i++)col.push_back(1);for(int i=0;i<2;i++)uv.push_back(0);}Json indices=Json::array();for(const auto& face:piece.at("faces"))for(const auto& i:face)indices.push_back(i);Json g={{"attributes",{{"position",attr(pos,3)},{"color",attr(col,3)},{"uv",attr(uv,2)}}},{"index",indices},{"groups",Json::array()}};g=updateGeometryFabricUV(piece,g,obj(piece,"fabric"))["geometry"];normals(g);return g;}
Json syncGeometry(const Json& piece,const Json& geometry,const Json& /*project*/){Json g=geometry;if(!g.contains("attributes")||!g["attributes"].contains("position")||size_t(g["attributes"]["position"].value("count",0))!=piece.at("particles").size())return {{"updated",false},{"geometry",g}};auto p=values(g,"position");size_t k=0;for(const auto& particle:piece.at("particles")){auto v=vec(particle.at("position"));for(double x:v)p[k++]=f32(x);}g["attributes"]["position"]=attr(p,3,true);normals(g);sphere(g);return {{"updated",true},{"geometry",g},{"visualWrapAssistSupported",false}};}
static double linear(int c){double x=c/255.;return x<.04045?x*.0773993808:std::pow(x*.9478672986+.0521327014,2.4);}
static std::array<double,3> rgb(int r,int g,int b){return {linear(r),linear(g),linear(b)};}
static std::array<double,3> blend(std::array<double,3> a,std::array<double,3> b,double t){return {a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t};}
Json syncAnalysisColors(const Json& piece,const Json& geometry,const std::string& mode){Json g=geometry;if(!g.contains("attributes")||!g["attributes"].contains("color"))return {{"updated",false},{"geometry",g}};auto colors=values(g,"color");auto cold=rgb(79,114,255),middle=rgb(241,200,77),hot=rgb(255,77,82),easeMiddle=rgb(91,212,139);size_t i=0;for(const auto& p:piece.at("particles")){std::array<double,3> c={1,1,1};if(mode=="pressure"||mode=="strain"||(mode!="surface"&&mode!="ease")){double t=std::min(1.,mode=="pressure"?get(p,"pressureIndex"):get(p,"strain")/.16);c=t<.5?blend(cold,middle,t*2):blend(middle,hot,(t-.5)*2);}else if(mode=="ease"){double e=std::max(0.,get(p,"easeCm"));c=e<2?blend(hot,easeMiddle,e/2):blend(easeMiddle,cold,std::min(1.,(e-2)/4));}for(double x:c){if(i>=colors.size())throw std::runtime_error("color attribute too small");colors[i++]=f32(x);}}g["attributes"]["color"]=attr(colors,3,mode!="surface");return {{"updated",true},{"geometry",g}};}
}
